module seqdet(input clk, input rst_n, input d, output reg hit);
  reg [1:0] s; // 0 none,1 "1",2 "10",3 "101"
  always @(posedge clk) begin
    if (!rst_n) begin s<=0; hit<=0; end
    else begin
      hit <= (s==3) & d;
      case (s)
        0: s <= d ? 1 : 0;
        1: s <= d ? 1 : 2;
        2: s <= d ? 3 : 0;
        3: s <= d ? 1 : 2;
      endcase
    end
  end
endmodule

module seqdet(input clk, input rst_n, input d, output reg hit);
  reg s1, s0;
  always @(posedge clk) begin
    if (!rst_n) begin s1<=0; s0<=0; hit<=0; end
    else begin
      s0 <= d;
      s1 <= d ? (s1&~s0) : s0;
      hit <= d & s1 & s0;
    end
  end
endmodule
